// ── FIX 1: Eager Loading with .Include() ──
var users = await db.Users
    .Include(u => u.Orders)    // JOIN in SQL
    .ToListAsync();            // 1 query!

foreach (var user in users) {
    Console.WriteLine($"{user.Name}: {user.Orders.Count} orders");
    // Orders already loaded — no extra queries
}

// ── FIX 2: Projection with .Select() (BEST) ──
var summary = await db.Users
    .Select(u => new {
        u.Name,
        OrderCount = u.Orders.Count(),
        TotalSpent = u.Orders.Sum(o => o.Amount)
    })
    .ToListAsync(); // 1 optimized query!
// Only fetches Name, Count, Sum — minimal data transfer

// ── FIX 3: Split Query (multiple collections) ──
var users = await db.Users
    .Include(u => u.Orders)
    .Include(u => u.Reviews)    // 2 collections = Cartesian explosion!
    .AsSplitQuery()             // splits into 3 separate queries
    .ToListAsync();

