// ── Default: WITH tracking (for updates) ──
var user = await db.Users.FirstAsync(u => u.Id == 1);
user.Name = "Updated Name";
await db.SaveChangesAsync();  // works! Change tracker detects modification

// ── AsNoTracking: read-only (faster) ──
var users = await db.Users
    .AsNoTracking()              // no change tracking!
    .Where(u => u.IsActive)
    .ToListAsync();
// 30-50% faster, less memory
// But: db.SaveChangesAsync() won't detect changes to these entities

// ── Set as default for the entire context ──
public class ReadOnlyDbContext : DbContext {
    public ReadOnlyDbContext(DbContextOptions options) : base(options) {
        ChangeTracker.QueryTrackingBehavior = QueryTrackingBehavior.NoTracking;
    }
}

// ── AsNoTrackingWithIdentityResolution ──
var orders = await db.Orders
    .AsNoTrackingWithIdentityResolution()  // no tracking + dedup
    .Include(o => o.User)
    .ToListAsync();
// If User #1 has 5 orders, you get ONE User instance, not 5 copies

// ── Real-world pattern: read vs write contexts ──
// ReadContext → always AsNoTracking (for API GETs)
// WriteContext → with tracking (for POST/PUT/DELETE)

// ── Approach 1: Direct DbContext (simple apps) ──
[ApiController, Route("api/users")]
public class UsersController(AppDbContext db) : ControllerBase {
    [HttpGet]
    public async Task<IActionResult> Get() =>
        Ok(await db.Users.AsNoTracking().ToListAsync());
}
// Simple, direct, no extra abstraction

// ── Approach 2: Repository (complex domains) ──
public interface IOrderRepository {
    Task<Order?> GetByIdAsync(int id);
    Task<List<Order>> GetOverdueOrdersAsync();
    Task<List<Order>> GetByCustomerAsync(int customerId);
    void Add(Order order);
}

public class OrderRepository : IOrderRepository {
    private readonly AppDbContext _db;
    public OrderRepository(AppDbContext db) => _db = db;

    public async Task<Order?> GetByIdAsync(int id) =>
        await _db.Orders.Include(o => o.Items).FirstOrDefaultAsync(o => o.Id == id);

    public async Task<List<Order>> GetOverdueOrdersAsync() =>
        await _db.Orders
            .Where(o => o.DueDate < DateTime.UtcNow && o.Status != OrderStatus.Paid)
            .OrderBy(o => o.DueDate)
            .ToListAsync();

    public void Add(Order order) => _db.Orders.Add(order);
}

